using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Geometry.FiniteGeometry;

internal sealed class ProjectivePlaneIntegerLatticeDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Geometry/FiniteGeometry/ProjectivePlaneIntegerLattice.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Integer incidence lattices on every actual finite nondegenerate projective plane.",
        H("Exact projective-plane integer incidence"), Blocks(
            Paragraph(Text("Let P and L be the original finite point and line types with a Mathlib Configuration.ProjectivePlane instance. Write q for its derived order, so q>=2 and both cardinalities are q^2+q+1. Each line contains q+1 points and each point lies on q+1 lines. Distinct lines meet once and distinct points have one joining line. These standard geometric facts are reused from Thomas Browning's Mathlib Configuration source. No plane is postulated at an arbitrary integer order. Singer's 1938 cyclic trace construction is geometry context only; it does not supply the integer-lattice inference.")),
            Node("row", "Original line indicators", "row l x is the integer 0 or 1 according to original incidence x in l.", DescribeRole.Definition),
            Node("incidence", "Original integer potentials", "F(a)(x)=sum_l row(l,x)*a(l), for arbitrary signed integer coefficients on ALL original lines.", DescribeRole.Definition),
            Node("lineSum", "Original line sums", "h_l(z)=sum_x row(l,x)*z(x), with all sums in the ambient integers.", DescribeRole.Definition),
            Node("lattice", "Exact image", "M is exactly range F in Z^P. It is neither a saturation nor a rational span.", DescribeRole.Definition),
            Node("q", "The derived integer order", "q is Mathlib's derived order of this actual projective plane, cast to the integers.", DescribeRole.Definition),
            Node("q_ge_two", "Nondegeneracy forces order at least two", "The original finite nondegenerate plane has integer order q at least two.", DescribeRole.Theorem),
            Node("row_total", "Each original line has q+1 points", "The sum over original point coordinates of row(l,x) is q+1.", DescribeRole.Theorem),
            Node("column_total", "Each original point has q+1 incident lines", "The sum over original lines of row(l,x) is q+1.", DescribeRole.Theorem),
            Node("row_gram", "Original-line intersections", "The integer sum over points of row(l,x)*row(k,x) is q+1 if l=k and one otherwise.", DescribeRole.Theorem),
            Node("column_gram", "Original-point pencils", "The integer sum over lines of row(l,x)*row(l,y) is q+1 if x=y and one otherwise.", DescribeRole.Theorem),
            Node("total_incidence", "Total mass identity", "For every integer potential a, sum_x F(a)(x)=(q+1)*sum_l a(l). Interchanging finite sums uses the actual q+1 line cardinality.", DescribeRole.Theorem),
            Node("lineSum_incidence", "Line mass identity", "For every original line l and integer potential a, h_l(F(a))=q*a(l)+sum_k a(k). The self-intersection contributes q+1 and every other original line contributes one.", DescribeRole.Theorem),
            Node("incidence_injective", "Unique original potentials", "F is injective on Z^L. Equality of totals fixes the coefficient total, and equality of original line sums fixes each integer coefficient. Only nonzero integer factors are cancelled.", DescribeRole.Theorem),
            Node("integer_reconstruction", "Unique integer reconstruction", "For every integer z and integer s satisfying the total equation and every original-line divisibility, there is exactly one original integer potential a with F(a)=z, total coefficient sum s, and a(l)=(h_l(z)-s)/q after divisibility is known. Injectivity supplies uniqueness.", DescribeRole.Theorem),
            Node("mem_lattice_iff", "Divisibility-certified reconstruction", "For every z in Z^P, z lies in M iff there is an INTEGER s with sum_x z(x)=(q+1)*s and q divides h_l(z)-s for EVERY original line l. After these divisibilities, the integer coefficient is (h_l(z)-s)/q. The dual pair-count identity gives q*F(a)(x)=q*z(x) at each original point; ambient integer cancellation reconstructs z.", DescribeRole.Theorem),
            Node("indicator", "Boolean original supports", "indicator S is 1 on the original finite support S and 0 at every other original point.", DescribeRole.Definition),
            Node("boolean_mem_lattice_iff", "Complete proper Boolean closure", "For every nonempty proper original support S, indicator S is in M iff S is an original line. If indicator S=F(a), total mass gives 1<=s<=q. Line sums give 0<=q*a(l)+s<=q+1. If s>=2 all coefficients are nonpositive, contradicting their positive sum. For s=1 they are all 0 or 1 and exactly one is 1. This excludes ALL hidden larger proper Boolean members, not merely extra generator rows.", DescribeRole.Theorem),
            Node("unit", "Original integer unit vectors", "unit x is the indicator of the singleton original point x.", DescribeRole.Definition),
            Node("unit_mem_lattice_iff", "The signed unit ideal", "For every original x and every signed integer k, k*e_x is in M iff q*(q+1) divides k. A line avoiding x forces q to divide the integer coefficient total. The upper certificate is (q+1)*W_x-T, with W_x=sum_{l contains x}[l]=q*e_x+U and T=sum_l[l]=(q+1)*U.", DescribeRole.Theorem),
            Node("difference_mem_lattice_iff", "The signed difference ideal", "For all distinct original x,y and all signed integer k, k*(e_x-e_y) is in M iff q divides k. The coefficient total is zero, and a line through x but not y forces the lower bound. The upper certificate is W_x-W_y.", DescribeRole.Theorem),
            Node("constant_mem_lattice_iff", "The signed full-total ideal", "For every signed integer k, k*U is in M iff q+1 divides k. Since n=1+q*(q+1), the total equation gives k=(q+1)*(s-q*k). The upper certificate uses coefficient 1 on every original line.", DescribeRole.Theorem),
            Paragraph(Text("The new reusable inference is integer reconstruction, complete Boolean closure and the exact signed ideals, derived here from the supplied native proof and Mathlib geometry. This is repo-derived content, without an external novelty or priority claim. Public identities serve the reconstruction and closure deductions; internal sum and geometric helpers have live consumers. Utility none: these are universal symbolic theorems, not finite enumerations, numeric reductions or certified instances.")),
            Paragraph(Text("In the universal quotient Z^P/M these ideals identify the exact annihilators of original units, differences and the full total. In particular nonzero q-torsion in original differences is retained; no cancellation is performed in this quotient. Each original point occurs in q+1 complete minimal Boolean rows, so this family genuinely exceeds incidence at most two, with unbounded q whenever actual planes exist. Primitive-free refers only to the original units and differences, not all primitive integer vectors: the line rows themselves are primitive.")),
            Paragraph(Text("Information-escape registration is unfinished for the nine public theorems; the source-bound audit gap is tracked at https://github.com/the-omega-institute/trureturing/issues/22019. The mathematical kernel check is separate from this incomplete registration. No declared_validated claim is made.")),
            Paragraph(Text("Mere line-zero equations in an arbitrary target group do not establish this complete Boolean closure. Further quotienting by the full-total vector makes line complements zero too; pair-intersection line sums still rule out original unit or difference collapse for q>=2. Thus an arbitrary group transfer requires a completeness hypothesis on ALL minimal zero supports. Exact orders stated here concern the universal quotient, not every target group. No ordering theorem, formal Good theorem, unrestricted integral blocker, general Good or AM result is claimed."))
        ), []));
    private static DocumentBlock Node(string name, string title, string prose, DescribeRole role) =>
        Describe.Lean(DescribeId.Create("plane-integer-" + name.Replace('_', '-').ToLowerInvariant()),
            DeclarationHandle.Create(Prefix + name), H(title), StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(prose))), role);
}
